// Embedded Roboto fonts fallback for serverless environments (Vercel, Netlify)
// where filesystem access to public/fonts may be restricted or missing.

const ROBOTO_MEDIUM_LATIN_B64 = "";
const ROBOTO_VIETNAMESE_B64 = "";
const ROBOTO_MEDIUM_VN_B64 = "";

export function getEmbeddedRobotoFonts(): Array<{
  name: string;
  data: Buffer;
  weight: 400 | 500;
  style: "normal";
}> {
  const regularLatin = Buffer.from(ROBOTO_MEDIUM_LATIN_B64, "base64");
  const regularVn = Buffer.from(ROBOTO_VIETNAMESE_B64, "base64");
  const mediumLatin = regularLatin;
  const mediumVn = Buffer.from(ROBOTO_MEDIUM_VN_B64, "base64");

  return [
    { name: "Roboto", data: regularLatin, weight: 400, style: "normal" },
    { name: "Roboto", data: regularVn, weight: 400, style: "normal" },
    { name: "Roboto", data: mediumLatin, weight: 500, style: "normal" },
    { name: "Roboto", data: mediumVn, weight: 500, style: "normal" },
  ];
}
